import{_ as o,o as t,c as a,ag as s}from"./chunks/framework.2EHAL5nC.js";const p=JSON.parse('{"title":"Upgrade guide","description":"","frontmatter":{},"headers":[],"relativePath":"upgrade.md","filePath":"upgrade.md","lastUpdated":1794896270000}'),d={name:"upgrade.md"};function i(c,e,n,r,l,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="upgrade-guide" tabindex="-1">Upgrade guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade guide&quot;">​</a></h1><h2 id="upgrading-the-command-and-an-application" tabindex="-1">Upgrading the command and an application <a class="header-anchor" href="#upgrading-the-command-and-an-application" aria-label="Permalink to &quot;Upgrading the command and an application&quot;">​</a></h2><ol><li><p>The command: <code>rustcms self-update</code> replaces it with the latest release (<code>--version v0.4.0</code> for a given one, older included). It works when the <a href="./getting-started/installation.html#installing-the-rustcms-command">install script</a> installed it; a command built with <code>cargo install</code> is updated the same way it was installed. <code>rustcms --version</code> shows the version and the platform.</p></li><li><p>An application: in its directory, <code>rustcms upgrade</code> moves it to the command&#39;s version:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # what changes in Cargo.toml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # writes it, then updates Cargo.lock</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>It sets the tag of <code>rustcms</code> and <code>rustcms-testing</code> (always the same), the <code>sea-orm</code> pins of that version and <code>[package.metadata.rustcms] version</code>, keeping your comments and features. If Cargo cannot resolve the result, <code>Cargo.toml</code> and <code>Cargo.lock</code> are put back. It refuses to go back to an older version (unless <code>--force</code>), and leaves alone a dependency on a local <code>path</code>, inherited from a workspace, renamed, or from another repository: change those by hand. Then follow the section of that version below, and commit <code>Cargo.toml</code> and <code>Cargo.lock</code> together.</p><p>To upgrade to another version than the command&#39;s, install that command first (<code>rustcms self-update --version vX.Y.Z</code>).</p></li></ol><h2 id="from-0121-to-0130" tabindex="-1">From 0.12.1 to 0.13.0 <a class="header-anchor" href="#from-0121-to-0130" aria-label="Permalink to &quot;From 0.12.1 to 0.13.0&quot;">​</a></h2><p>No migration. To roll back, install 0.12.1 again; no data changes shape.</p><ul><li><p><strong>SQLite 3.54 (security, RUSTSEC-2026-0459).</strong> No sqlx release bundles it yet, and a <code>[patch.crates-io]</code> in RustCMS does not reach an application: add the section below to the <code>Cargo.toml</code> at your workspace&#39;s root (the application&#39;s own, or the parent workspace&#39;s for an application inside one), then run <code>cargo update -p libsqlite3-sys</code>. <code>rustcms new</code> writes it for new applications, except with <code>--in-workspace</code>: add it to the parent workspace&#39;s root. A later release says when to remove it.</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">patch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crates-io</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlx = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/launchbadge/sqlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10462fa4414c6c7f1ed1d39bb31678e3b726878c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlx-core = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/launchbadge/sqlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10462fa4414c6c7f1ed1d39bb31678e3b726878c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlx-macros = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/launchbadge/sqlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10462fa4414c6c7f1ed1d39bb31678e3b726878c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlx-macros-core = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/launchbadge/sqlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10462fa4414c6c7f1ed1d39bb31678e3b726878c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlx-mysql = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/launchbadge/sqlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10462fa4414c6c7f1ed1d39bb31678e3b726878c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlx-postgres = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/launchbadge/sqlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10462fa4414c6c7f1ed1d39bb31678e3b726878c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sqlx-sqlite = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/launchbadge/sqlx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, rev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10462fa4414c6c7f1ed1d39bb31678e3b726878c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Only a process that opens a database file (with its <code>-wal</code>) written by a less trusted party is exposed; PostgreSQL and MySQL applications are not.</p></li><li><p><strong>New schema vocabulary.</strong> The panel and the server move together (the admin panel is embedded): nothing to do, unless an application builds <code>InputSchema</code> or <code>LayoutSchema</code> by hand (new members <code>number</code>, <code>shownWhen</code>, <code>clearWhenHidden</code>).</p></li><li><p><strong>Relationship select search.</strong> Each word of a search must match one of the title&#39;s fields: with <code>title(&quot;name&quot;)</code>, a search of several words no longer matches only that exact phrase. Titles with an empty value are left out of <code>titles()</code>.</p></li><li><p><strong>Extensions: SDK <code>ui</code> 3.</strong> Bundles built with <code>ui: 2</code> keep working. To use <code>registerEntry</code> or the SDK&#39;s <code>Infolist</code>, copy the new SDK (<code>rustcms make:sdk</code>, which points at the registrations to move), set <code>Requires { ui: 3 }</code> and rebuild (<code>npm run build</code>).</p></li><li><p><strong>Rust API.</strong> New variants: <code>Component::Entry</code> (forms hold entries in infolists), <code>ComponentSchema::Entry</code>, <code>PageView::Infolist</code>. An exhaustive <code>match</code> on one of these enums needs an arm for it (or <code>_</code>). Code implementing <code>DynResource</code> itself (not through <code>Resource</code>) adds <code>computed</code> and <code>field_locks_media_or_secret</code>; struct literals of <code>RepeaterSchema</code> add <code>create_components</code>.</p></li><li><p><strong><code>lock_parent</code> cannot target the media library</strong> (boot refuses it): media rows are locked after every other record of a write.</p></li><li><p><strong>Name clash.</strong> <code>rustcms_admin::Condition</code> (form conditions) can clash with <code>sea_orm::Condition</code> when an application glob-imports both (<code>use rustcms_admin::*; use sea_orm::*;</code>): import the one you use by name.</p></li></ul><h2 id="from-0120-to-0121" tabindex="-1">From 0.12.0 to 0.12.1 <a class="header-anchor" href="#from-0120-to-0121" aria-label="Permalink to &quot;From 0.12.0 to 0.12.1&quot;">​</a></h2><p>No migration. To roll back, install 0.12.0 again.</p><ul><li>Only new applications change. To format an existing one as new ones are, copy <a href="https://github.com/irisvn/RustCMS-Core/blob/v0.12.1/rustfmt.toml" target="_blank" rel="noreferrer"><code>rustfmt.toml</code></a> to its root and run <code>cargo fmt</code>; generators find their markers wherever they sit in the builder chains.</li></ul><h2 id="from-0110-to-0120" tabindex="-1">From 0.11.0 to 0.12.0 <a class="header-anchor" href="#from-0110-to-0120" aria-label="Permalink to &quot;From 0.11.0 to 0.12.0&quot;">​</a></h2><p>No migration. To roll back, install 0.11.0 again; no data changes shape.</p><ul><li><strong>Behaviour change: the media and exports cleanups need the scheduler.</strong> They are now framework schedules, <code>rustcms.media-prune.&lt;disk&gt;</code> (every minute) and <code>rustcms.exports-prune.&lt;disk&gt;</code> (every 10 minutes), run only by <code>serve</code> with <code>[schedule] enabled</code>, once per slot across instances. They no longer run in <code>queue:work</code> or console commands and take no Redis lease. If no instance runs <code>serve</code> with the scheduler, cron <code>media:prune</code> and <code>schedule:run rustcms.exports-prune.local</code> (or <code>.s3</code>).</li><li>Temporary files an instance staged (uploads, exports, imports) are removed by that instance after an hour: every <code>serve</code> and <code>queue:work</code>, every 10 minutes. <code>media::prune</code>, <code>exports::prune</code> and <code>imports::prune</code> no longer sweep them; call <code>rustcms::storage::sweep_staging</code> if your code relied on it.</li><li>New <code>[app] mode</code> (<code>full</code> by default, nothing changes). In <code>api</code> mode (<code>serve --api-only</code>), <code>queue.enabled</code> and <code>schedule.enabled</code> left out are <code>false</code> (<a href="./digging-deeper/instances.html#api-mode">API mode</a>).</li><li>New opt-in settings <code>auth.permission_generation_cache_ms</code> and <code>auth.jwt.session_cache_ms</code>, both <code>0</code> (unchanged behaviour).</li><li><code>MediaResource</code> now implements <code>after_trash</code> and <code>after_restore</code> (for media hooks); nothing changes for applications.</li></ul><h2 id="from-0103-to-0110" tabindex="-1">From 0.10.3 to 0.11.0 <a class="header-anchor" href="#from-0103-to-0110" aria-label="Permalink to &quot;From 0.10.3 to 0.11.0&quot;">​</a></h2><p>No migration. Read the first points before upgrading: they can make a request a 422 or stop the boot. To roll back, install 0.10.3 again; no data changes shape.</p><ul><li><code>rustcms docs</code> opens the guide of your version online (<code>https://irisvn.github.io/RustCMS/v/X.Y.Z/</code>); the command no longer carries an offline copy. The guide&#39;s sources are Markdown files in RustCMS-Core (<code>docs/guide/src</code>).</li><li>The hourly auth cleanup (expired sessions, ended JWT sign-ins, reset and invitation links, old audit entries) and the idempotency cleanup are now framework schedules, <code>rustcms.auth-prune</code> and <code>rustcms.idempotency-prune</code>: only <code>serve</code> runs them, with <code>[schedule] enabled</code>, on the hour (UTC), once across instances. They no longer run in <code>queue:work</code>, console commands or tests, and take no Redis lease. If no instance runs <code>serve</code> with the scheduler, cron <code>schedule:run rustcms.auth-prune</code> (or <code>session:prune</code>, <code>audit:prune</code>) and <code>idempotency:prune</code>. They appear on System → Schedules and in <code>schedule:list</code>; holders of <code>schedules.manage</code> can Run them now. Application schedules still cannot use the <code>rustcms.</code> prefix. No migration.</li><li><strong>Behaviour change: static options are validated.</strong> A client write to a resource (create, update, a relation create, a CSV import row) whose value is not one of a <code>SelectInput</code>&#39;s or <code>CheckboxList</code>&#39;s <code>.options(…)</code> is now a 422 (<code>not_option</code>; a checkbox list also <code>invalid</code> when not a list and <code>given_twice</code> for a repeated item); it was stored before. Records already holding other values keep them until the field is written. Clients and imports sending values outside the options must send an option, or the options must list the value. Hooks and action handlers are not affected.</li><li>New boot failures (the application refuses to start): a select option that is not a value of its column (<code>12</code> for an <code>i64</code> column, write <code>&quot;12&quot;</code>) or that would be stored as another value (<code>&quot;10.555&quot;</code> on a column of scale 2, more digits than a decimal&#39;s precision, <code>0.1</code> on an <code>f32</code> column, a timestamp finer than microseconds); options on a <code>SecretInput</code> or <code>SecretMapInput</code>; a <code>CheckboxList</code> on a column that is not JSON; a field in several inputs that do not offer the same options (another set, a select and a checkbox list, or one of them without options). See <a href="./admin/forms.html#options-are-not-validated">options</a>. The schema now shows select options in canonical form (<code>&quot;0012&quot;</code> → <code>&quot;12&quot;</code>), and a matched select value is stored as its option (<code>&quot;10.505&quot;</code> → <code>&quot;10.50&quot;</code>). No migration.</li><li>A background export over its limits now fails with the reason <code>too_many_to_export</code> or <code>too_many_matches</code> instead of <code>revoked</code>. A client of <code>GET {admin}/api/exports</code> that maps reasons should add both (unknown reasons should already show as a generic failure).</li><li>The panel&#39;s sockets refuse to send messages larger than <code>[realtime] max_message_bytes</code> (it was a fixed 64 KiB): with a lower value, pages that sent up to 64 KiB now get <code>false</code> from <code>send</code> for larger messages. Keep the value the same on every instance; open tabs keep the limit they loaded until reloaded.</li><li>Export and import pruning only cleans its own disk (<code>[storage] disk</code>). After a change of disk, expired exports and imports of the old disk stay (rows and files) until a process configured with the old disk boots and prunes them, or you delete them yourself (they are no longer listed nor downloadable once expired). No migration.</li></ul><h2 id="from-0102-to-0103" tabindex="-1">From 0.10.2 to 0.10.3 <a class="header-anchor" href="#from-0102-to-0103" aria-label="Permalink to &quot;From 0.10.2 to 0.10.3&quot;">​</a></h2><ul><li>Nothing to change. On phones a record page&#39;s Edit and Delete are in its ⋯ menu: end-to-end tests at phone widths open the menu first.</li></ul><h2 id="from-0101-to-0102" tabindex="-1">From 0.10.1 to 0.10.2 <a class="header-anchor" href="#from-0101-to-0102" aria-label="Permalink to &quot;From 0.10.1 to 0.10.2&quot;">​</a></h2><ul><li>Vocabulary 11: layouts <code>split</code> and <code>pane</code>, <code>collapsed</code> and <code>compact</code> on sections, <code>prefix</code> and <code>suffix</code> on text inputs, <code>FormSchema.width</code>. An older admin SPA shows the banner and lays such forms out as plain groups; extensions that check the vocabulary version should accept 11. Exhaustive matches on <code>LayoutType</code> and clients that build <code>LayoutSchema</code>, <code>InputSchema</code> or <code>FormSchema</code> values by hand need the new members.</li><li>The default theme&#39;s <code>success</code> and <code>warning</code> colors are green and amber (they were grays): set them with <code>Theme::color</code> to keep the old look.</li><li>No migration.</li></ul><h2 id="from-0100-to-0101" tabindex="-1">From 0.10.0 to 0.10.1 <a class="header-anchor" href="#from-0100-to-0101" aria-label="Permalink to &quot;From 0.10.0 to 0.10.1&quot;">​</a></h2><ul><li><strong>Run <code>rustcms migrate</code></strong> (<code>m20261201_000022_add_alt_to_media</code>, a nullable column): <code>serve</code> does not wait for it, and media queries fail until it has run. 0.10.0 binaries read the migrated database: to roll back, run them with <code>migrate --allow-newer</code> (or <code>[database] allow_newer_migrations</code>); leave the column in place (<code>migrate:rollback</code> would undo the application&#39;s own latest migrations first).</li><li><strong><code>media.update</code> now grants something</strong>: renaming one&#39;s own files and editing their alternative text (before, updates were always refused); with <code>media.manage_all</code>, everyone&#39;s files. Review roles that hold <code>media.*</code> as a whole.</li><li>The navigation and the dashboard&#39;s resource cards follow registration order, not slugs: use <code>ResourceMeta::sort</code> to keep an order.</li><li>Every <code>.bulk()</code> action is also offered on rows where the record&#39;s abilities allow it; an action offered only for a selection is not supported (<code>visible_when</code> also applies when the action runs, so hiding it on every row would leave a bulk run nothing to process).</li><li>Action dialogs no longer say &quot;Run&quot;: their button is the action&#39;s label without &quot;…&quot; (or <code>submit_label</code>); empty values read &quot;Not set&quot;. Update end-to-end selectors.</li><li>Vocabulary 10: <code>ActionSchema.primary</code> and <code>submitLabel</code>, <code>ColumnSchema.hideBelow</code>; per-record <code>abilities</code> include <code>visible_when</code>. An older admin SPA shows the banner and every offered action as a button; extensions that check the vocabulary version should accept 10.</li><li>Struct literals: <code>ActionOutcome</code> has <code>message</code> and <code>open</code> (add <code>..Default::default()</code>); <code>media::entity::Model</code> / <code>ActiveModel</code> have <code>alt</code>. Clients that build wire types by hand gain <code>MediaItem.alt</code>, <code>RecentColumn.valueType</code>, <code>options</code> and <code>column</code>, and <code>RecentRecord.data</code>.</li><li><code>Action::new</code> is unchanged; handlers that return an outcome use <code>Action::with_outcome</code>.</li></ul><h2 id="from-090-to-0100" tabindex="-1">From 0.9.0 to 0.10.0 <a class="header-anchor" href="#from-090-to-0100" aria-label="Permalink to &quot;From 0.9.0 to 0.10.0&quot;">​</a></h2><ul><li>Rich text documents have a version 2 (tables, embeds, callouts, image captions and widths). Stored version 1 documents stay valid and are read as they are, and the panel keeps writing version 1 unless a document uses a version 2 part. Nothing to migrate. To rewrite stored documents anyway, map each value through <code>rustcms::admin::rich_text::upgrade_value</code> (only <code>version</code> changes).</li><li><strong>Rolling back to 0.9, or a 0.9 reader of the same database</strong> (another service, a replica during a rolling deploy): documents saved with a version 2 part (table, embed, callout, image caption or width) are refused by 0.9&#39;s <code>rich_text::parse</code>, and the 0.9 panel shows them read-only. Deploy every reader first; before rolling back, remove those parts or keep 0.10. A headless consumer that parses documents itself should accept <code>&quot;version&quot;: 2</code> and the new nodes (see <a href="./admin/media.html#rich-text">Rich text</a>).</li><li><code>rich_text::Node</code> is <code>#[non_exhaustive]</code> and has new variants (<code>Table</code>, <code>Embed</code>, <code>Callout</code>); <code>Node::Image</code> now holds an <code>Image { media, alt, caption, width }</code>; <code>Document</code> has a <code>version</code> field. Exhaustive matches, patterns on <code>Node::Image { media, alt }</code> and struct literals need updating.</li><li><code>rich_text::to_html</code> keeps its signature but writes images as <code>&lt;figure&gt;&lt;img …&gt;&lt;/figure&gt;</code> and headings with an <code>id</code>. Use <code>to_html_with(&amp;doc, &amp;HashMap&lt;Uuid, ImageInfo&gt;)</code> to write image sizes, and <code>outline</code> for a table of contents.</li><li><code>PanelResponse</code> has an optional <code>uploads</code> field (the upload limits); admin clients that build <code>PanelResponse</code> values by hand need it.</li></ul><h2 id="from-082-to-090" tabindex="-1">From 0.8.2 to 0.9.0 <a class="header-anchor" href="#from-082-to-090" aria-label="Permalink to &quot;From 0.8.2 to 0.9.0&quot;">​</a></h2><ul><li>New permission <code>media.view_all</code> (run <code>permission:sync</code> to list it). Roles that held <code>media.manage_all</code> only to see other users&#39; files can hold <code>media.view_all</code> instead.</li><li><code>InputType</code> has a <code>BelongsToMany</code> variant, <code>InputSchema</code> a <code>links</code> field and <code>DynResource</code> a <code>link_options_new</code> method (exhaustive matches, struct literals and hand-written implementations need them). Admin clients see <code>vocabularyVersion</code> 9: an older admin SPA shows these inputs read-only and never sends them, and an extension that checks the vocabulary version should accept 9.</li><li><code>Resource::after_relation_change</code> is new: a link write never updates the parent row, so touch <code>updated_at</code> there if your application needs it.</li><li>Restores now call <code>after_restore</code>, whose default calls <code>after_save</code>: nothing changes unless you override it (then call <code>Self::after_save</code> from it if restores should still run your <code>after_save</code>).</li></ul><h2 id="from-081-to-082" tabindex="-1">From 0.8.1 to 0.8.2 <a class="header-anchor" href="#from-081-to-082" aria-label="Permalink to &quot;From 0.8.1 to 0.8.2&quot;">​</a></h2><p>Nothing needs to change (no rebuild of React pages either). A workaround that hid <code>session_changed</code> from reads may stay or go.</p><h2 id="from-080-to-081" tabindex="-1">From 0.8.0 to 0.8.1 <a class="header-anchor" href="#from-080-to-081" aria-label="Permalink to &quot;From 0.8.0 to 0.8.1&quot;">​</a></h2><p>Nothing needs to change. To survive automatic rollbacks, keep migrations additive and start the image with <code>migrate --allow-newer</code>. Deploy that image before adding migrations: a rollback only accepts newer migrations when the image it returns to is 0.8.1 or later with the flag (a 0.8.0 image still refuses). Run migrations once per deployment, not in every replica (<a href="./getting-started/deployment.html#upgrading">Deployment</a>).</p><h2 id="from-071-to-080" tabindex="-1">From 0.7.1 to 0.8.0 <a class="header-anchor" href="#from-071-to-080" aria-label="Permalink to &quot;From 0.7.1 to 0.8.0&quot;">​</a></h2><p>Run <code>rustcms migrate</code>: it adds <code>jobs.started_at</code>, <code>jobs.description</code> and the <code>job_runs</code> and <code>schedule_runs</code> tables. Then:</p><ul><li>Grant <code>schedules.view</code> (and <code>schedules.manage</code> for Run now) to the roles that should see System → Schedules (<code>rustcms permission:sync</code> declares them).</li><li><code>.run</code> schedules keep working; switch to <code>.task</code> to show a summary.</li><li>Job kinds starting with <code>rustcms.</code> are now refused (they are the framework&#39;s).</li><li>The Queue&#39;s <em>Scheduled</em> status is labelled <em>Delayed</em> (the API value stays <code>scheduled</code>).</li></ul><h2 id="from-070-to-071" tabindex="-1">From 0.7.0 to 0.7.1 <a class="header-anchor" href="#from-070-to-071" aria-label="Permalink to &quot;From 0.7.0 to 0.7.1&quot;">​</a></h2><p>Nothing needs to change. React pages&#39; dialogs get the close button without a rebuild; <code>rustcms make:sdk</code> adds <code>closeButton</code> and <code>closeDisabled</code> to the SDK&#39;s types.</p><h2 id="from-061-to-070" tabindex="-1">From 0.6.1 to 0.7.0 <a class="header-anchor" href="#from-061-to-070" aria-label="Permalink to &quot;From 0.6.1 to 0.7.0&quot;">​</a></h2><p>Most applications need no change; update links of your own to theme files, and <code>PermissionInfo</code> struct literals, if you have any.</p><ul><li>The Roles page now groups permissions by area: resource matrix cells under &quot;Resources&quot;, the built-in users, roles and permissions permissions under &quot;System&quot;, the rest under &quot;Other&quot; until you declare areas (<code>permission_area</code>, <code>permission_meta</code>).</li><li>Theme files moved from <code>{admin}/assets/ext/</code> to <code>{admin}/assets/brand/</code> (<code>theme.css</code>, <code>logo</code>, <code>favicon</code>). Change any link of your own to the old paths; the panel&#39;s pages need nothing.</li><li>The sign-in pages now show your <code>brand(…)</code> name and logo instead of &quot;rustcms&quot;.</li><li><code>PermissionInfo</code> (from <code>GET {admin}/api/system/permissions</code>) has new fields; code that builds it with a struct literal must add them.</li></ul><h2 id="from-060-to-061" tabindex="-1">From 0.6.0 to 0.6.1 <a class="header-anchor" href="#from-060-to-061" aria-label="Permalink to &quot;From 0.6.0 to 0.6.1&quot;">​</a></h2><p>Nothing needs to change. Users can now pick Light, Dark or System; your <code>Theme::color_scheme</code> is the default until they do. To use <code>useColorScheme()</code> in a React page, run <code>rustcms make:sdk</code>, then <code>npm run build</code> in <code>resources/admin</code>.</p><h2 id="from-051-to-060" tabindex="-1">From 0.5.1 to 0.6.0 <a class="header-anchor" href="#from-051-to-060" aria-label="Permalink to &quot;From 0.5.1 to 0.6.0&quot;">​</a></h2><p>Nothing needs to change: React pages built with <code>ui: 1</code> keep working.</p><p>To use <code>props.resources</code>, <code>props.toast</code> and the new components:</p><ol><li>Run <code>rustcms make:sdk</code>: it updates <code>resources/admin/sdk</code> (keeping files you edited) and lists the registrations to change.</li><li>Set <code>ui: 2</code> in those <code>Requires { … }</code>. A bundle built with the new SDK is refused while its provider still declares <code>ui: 1</code>.</li><li>Run <code>npm install &amp;&amp; npm run build</code> in <code>resources/admin</code>, then commit.</li></ol><h2 id="from-050-to-051" tabindex="-1">From 0.5.0 to 0.5.1 <a class="header-anchor" href="#from-050-to-051" aria-label="Permalink to &quot;From 0.5.0 to 0.5.1&quot;">​</a></h2><p>Nothing needs to change. <code>PanelResponse</code> (<code>home</code>), <code>ResourceInfo</code> (<code>sort</code>, <code>nav</code>) and <code>PageLink</code> (<code>sort</code>) have new fields: code that builds these structs with a literal must add them (they are normally only read).</p><h2 id="from-041-to-050" tabindex="-1">From 0.4.1 to 0.5.0 <a class="header-anchor" href="#from-041-to-050" aria-label="Permalink to &quot;From 0.4.1 to 0.5.0&quot;">​</a></h2><p>Nothing needs to change: v1 scripts (<code>extension_script</code>, <code>window.rustcms.registerPage</code> with <code>apiVersion: 1</code>) work as before.</p><ul><li>New, optional: <a href="./admin/react-pages.html">React pages</a> (<code>rustcms make:page &lt;Name&gt; --react</code>, <code>extension_script_v2</code>). They need Node 20.19+ or 22.12+ to build, not to compile or deploy the app.</li><li><code>GET {admin}/api/panel</code> has a new <code>permissions</code> list; a test that compares the whole response should expect it, and Rust code building a <code>PanelResponse</code> literal must add <code>permissions</code>.</li><li><code>{admin}/api/pages/{slug}/{*path}</code> is new: a page now answers its sub-paths too (with the page&#39;s permissions; read <code>ctx.page_path()</code> in <code>data</code> to tell them apart).</li></ul><h2 id="from-040-to-041" tabindex="-1">From 0.4.0 to 0.4.1 <a class="header-anchor" href="#from-040-to-041" aria-label="Permalink to &quot;From 0.4.0 to 0.4.1&quot;">​</a></h2><ul><li><code>rustcms migrate</code>: two new tables, <code>schedule_states</code> and <code>schedule_slots</code>.</li><li>Periodic work can move from your own <code>tokio::spawn</code> loops to <a href="./digging-deeper/scheduling.html">schedules</a>, which run once per slot across instances and only in <code>serve</code>.</li><li><code>rustcms::settings::{read, load, write}</code> take the keyring (<code>state.keyring()</code>) instead of <code>&amp;state.config().app.key</code>. <code>settings::get(&amp;state)</code> is unchanged.</li><li>New, optional: <code>APP_PREVIOUS_KEYS</code> (see <a href="./operations/app-key.html">Rotating APP_KEY</a>), and <a href="./digging-deeper/encryption.html">encrypted columns</a>.</li><li>The admin vocabulary is 8 (<code>secret_map</code> inputs). An extension that checks the vocabulary version should accept 8.</li></ul><h2 id="from-032-to-040" tabindex="-1">From 0.3.2 to 0.4.0 <a class="header-anchor" href="#from-032-to-040" aria-label="Permalink to &quot;From 0.3.2 to 0.4.0&quot;">​</a></h2><p><code>rustcms self-update</code>, then <code>rustcms upgrade</code> in each application. Nothing needs to change in your code.</p><ul><li>New <code>[realtime]</code> keys, all optional: <code>socket_revalidate_secs</code>, <code>max_message_bytes</code>, <code>send_timeout_secs</code> (<a href="./getting-started/configuration.html">Configuration</a>). The other keys already existed.</li><li>The admin page&#39;s CSP now also lists <code>ws(s)://</code> for the panel&#39;s origins in <code>connect-src</code>. A test that compares the header with <code>rustcms::admin::spa::CONTENT_SECURITY_POLICY</code> should use <code>content_security_policy(&amp;origins)</code> instead.</li><li><code>{admin}/api/x</code> belongs to your <code>AdminRoutes</code>: nothing built in lives there.</li><li>Behind a proxy, if you add WebSocket routes, see the <a href="./security/production.html">production checklist</a>.</li></ul><h2 id="from-031-to-032" tabindex="-1">From 0.3.1 to 0.3.2 <a class="header-anchor" href="#from-031-to-032" aria-label="Permalink to &quot;From 0.3.1 to 0.3.2&quot;">​</a></h2><p>Only the command changed (new <code>doctor</code>, <code>upgrade</code>, <code>self-update</code>, <code>docs</code>). Install it again with the install script (0.3.1 has no <code>self-update</code>), then <code>rustcms upgrade</code> in each application.</p><h2 id="applications-made-before-031" tabindex="-1">Applications made before 0.3.1 <a class="header-anchor" href="#applications-made-before-031" aria-label="Permalink to &quot;Applications made before 0.3.1&quot;">​</a></h2><p>They depend on <code>rustcms = &quot;0.3.0&quot;</code> (not on crates.io) or on a local <code>path</code>. <code>rustcms upgrade</code> moves a version dependency to the Git tag; a <code>path</code> is changed by hand, keeping your features:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rustcms = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/irisvn/RustCMS-Core&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tag = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v0.3.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dev-dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rustcms-testing = { git = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/irisvn/RustCMS-Core&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tag = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;v0.3.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="from-010-alpha0-or-a-02-build-to-030" tabindex="-1">From 0.1.0-alpha.0 (or a 0.2 build) to 0.3.0 <a class="header-anchor" href="#from-010-alpha0-or-a-02-build-to-030" aria-label="Permalink to &quot;From 0.1.0-alpha.0 (or a 0.2 build) to 0.3.0&quot;">​</a></h2><ol><li>Update the <code>rustcms</code> dependency, then run <code>rustcms migrate</code> (new tables for media, JWT sign-ins, idempotency keys, locks, the audit log, settings, jobs, and <code>users.locale</code>). <code>serve</code> now also runs queue workers (set <code>queue.enabled = false</code> to keep them out of web instances).</li><li>Rust API changes: <ul><li>API routes: move them to <code>ApiRoutes</code> with an explicit <code>Access</code> per route (<a href="./basics/routing.html">Routing</a>); register them with <code>AuthProvider::new().api_permissions(&amp;api)</code> and <code>api.register(&amp;mut app)</code>.</li><li><code>RateLimiter::reserve</code>, <code>release</code> and <code>clear</code> are async (<code>.await</code> them).</li><li><code>Principal</code> and <code>rustcms::models::user::Model</code> have new fields (<code>locale</code>, <code>credential</code>): struct literals need them, or <code>..Default::default()</code>.</li><li><code>AppError::Conflict</code> has a new <code>reason</code> field.</li><li><code>SettingsAbilities</code> has a new <code>test</code> field; <code>SettingsPage::validate_in</code> (with the application) runs <code>validate</code> by default.</li><li><code>rustcms::models::user::Model</code> has <code>invitation_pending</code>, <code>invited_at</code>, <code>invited_by</code> (migrations <code>…000018</code>, <code>…000019</code>): struct literals need them (<code>..Default::default()</code> on <code>ActiveModel</code>s is unaffected). <code>rustcms-auth</code> now enables the core <code>mail</code> feature.</li><li>Mail: register <code>rustcms::mail::MailProvider</code> (and <code>AdminProvider::mail_settings()</code> for the page); in production with <code>driver = &quot;smtp&quot;</code> and <code>source = &quot;settings&quot;</code>, set <code>[mail] allowed_hosts</code>.</li><li>Functions that change credentials record an audit entry and take one more argument: <code>credentials::change_password</code> and <code>credentials::logout_everywhere</code> an <code>&amp;AuditContext</code>; <code>credentials::issue_token</code> and <code>jwt_session::{issue, rotate, logout}</code> a <code>&amp;RequestMeta</code> (both in <code>rustcms::audit</code>; <code>RequestMeta</code> is also an extractor).</li><li><code>InputType</code> has a <code>Secret</code> variant and <code>AdminPanel</code> a <code>settings</code> field (exhaustive matches and struct literals need them); admin clients see <code>vocabularyVersion</code> 5.</li><li>Resource slugs are limited to 64 bytes and action names to 57, and <code>user</code>, <code>role</code>, <code>permission</code>, <code>settings</code>, <code>session</code> (and <code>job</code>, <code>queue</code>, see below) are reserved (boot fails); <code>Ctx::new</code> records writes as its principal.</li><li><code>ActorKind</code> has a <code>Job</code> variant (exhaustive matches need it).</li><li><code>AdminPanel</code> has a <code>custom</code> field (<code>CustomPanel::empty(base)</code> in hand-built panels), <code>PanelResponse</code> a <code>pages</code> field and <code>ColumnSchema</code> <code>cell</code> / <code>props</code>; admin clients see <code>vocabularyVersion</code> 6.</li><li><code>SystemLinks</code> has <code>audit</code> and <code>queue</code> fields; resource schemas gain the <code>history</code> ability.</li><li>Resource slugs <code>job</code> and <code>queue</code> are reserved too (subjects of the Queue page&#39;s audit entries).</li><li>Actions: <code>data</code> sent to an action without a form is refused (422), and the request body may only hold <code>keys</code> and <code>data</code>. Declare what an action needs with <code>Action::form</code> (<a href="./admin/actions.html#actions-with-a-form">Actions</a>). Actions are admitted before the body is read: a policy deciding per record should override <code>Policy::admits</code> for abilities that need a permission. Actions the policy does not admit are no longer listed in the schema.</li><li>Run <code>rustcms migrate</code> (new <code>exports</code> and <code>imports</code> tables). <code>ResourceSchema.abilities</code> may hold <code>export</code>; <code>DynResource</code> has new methods (implementations outside the crate are not expected).</li><li><code>Relation</code> has new fields and <code>RelationSchema</code> a <code>kind</code>; <code>ActionSchema</code> a <code>form</code>; <code>ListQuery</code> a hidden <code>through</code> field (struct literals need <code>..Default::default()</code>). Admin clients see <code>schemaVersion</code> 2 and <code>vocabularyVersion</code> 7: an older admin SPA turns read-only.</li><li>Tests that build tables from entities instead of running migrations also need the <code>audit_logs</code> table (<a href="./basics/testing.html">Testing</a>).</li></ul></li><li>Optional: translate your labels. Add <code>lang/vi.toml</code>, register it with <code>AdminProvider::new().translations(&quot;vi&quot;, include_str!(&quot;../lang/vi.toml&quot;))</code>, and fill in what <code>rustcms lang:missing vi</code> lists.</li><li>API clients: error bodies gain <code>issues</code> and <code>formIssues</code> (and <code>reason</code> on 409); existing fields are unchanged.</li><li>Several instances: see <a href="./digging-deeper/instances.html">Several instances</a>.</li></ol><h2 id="application-layout-03" tabindex="-1">Application layout (0.3) <a class="header-anchor" href="#application-layout-03" aria-label="Permalink to &quot;Application layout (0.3)&quot;">​</a></h2><p>Applications are laid out like Laravel applications, inside <code>src/</code> (<a href="./getting-started/directory-structure.html">Directory structure</a>). Generators refuse an application in the old layout; move it once:</p><table tabindex="0"><thead><tr><th>Before</th><th>Now</th></tr></thead><tbody><tr><td><code>src/app.rs</code> (<code>build</code>)</td><td><code>src/bootstrap/mod.rs</code> (<code>build</code>) + <code>src/bootstrap/providers.rs</code></td></tr><tr><td>providers set up in <code>build</code></td><td><code>src/providers/{auth_service_provider,admin_panel_provider,app_service_provider}.rs</code></td></tr><tr><td><code>src/migrations/</code></td><td><code>src/database/migrations/</code> (keep the file names: they are recorded in <code>seaql_migrations</code>)</td></tr><tr><td><code>src/admin/post.rs</code></td><td><code>src/admin/resources/post_resource.rs</code></td></tr><tr><td><code>src/http/api/mod.rs</code> (<code>routes</code>)</td><td><code>src/routes/api.rs</code></td></tr><tr><td><code>src/http/api/posts/handlers.rs</code></td><td><code>src/http/controllers/post_controller.rs</code></td></tr><tr><td><code>src/http/api/posts/requests.rs</code></td><td><code>src/http/requests/post_request.rs</code></td></tr><tr><td><code>src/http/api/posts/json.rs</code></td><td><code>src/http/resources/post_resource.rs</code></td></tr><tr><td>a settings struct with its page</td><td><code>src/settings/&lt;x&gt;_settings.rs</code> + <code>src/admin/pages/&lt;x&gt;_settings_page.rs</code></td></tr><tr><td>a <code>&lt;app&gt;:seed</code> command</td><td><code>src/database/seeders/</code> + <code>rustcms db:seed</code></td></tr><tr><td><code>tests/*.rs</code></td><td><code>tests/feature/*.rs</code> listed in <code>tests/feature/main.rs</code>, helpers in <code>tests/support/mod.rs</code></td></tr><tr><td><code>assets/admin/&lt;vendor&gt;/*.js</code>, <code>*.css</code></td><td><code>resources/admin/js/&lt;vendor&gt;/</code>, <code>resources/admin/css/&lt;vendor&gt;/</code> (update the <code>include_str!</code> paths)</td></tr></tbody></table><p>Then:</p><ol><li><code>src/main.rs</code>: <code>Console::&lt;my_app::database::migrations::Migrator&gt;::new(my_app::bootstrap::build)</code>.</li><li>Add the generator anchors where generated lines go: <code>// rustcms:mods</code> (<code>src/lib.rs</code>), <code>// rustcms:resources</code> and <code>// rustcms:pages</code> (admin panel provider), <code>// rustcms:seeders</code>, <code>// rustcms:jobs</code>, <code>// rustcms:commands</code> (app service provider), <code>// rustcms:api-routes</code> (<code>src/routes/api.rs</code>), <code>// rustcms:tests</code> (<code>tests/feature/main.rs</code>), <code>// rustcms:extensions</code> (admin panel provider, for <code>make:page --script</code>). A new application from <code>rustcms new</code> shows every one.</li><li><code>rustcms migrate:status</code> lists every migration as applied: nothing to run.</li></ol>`,65)])])}const m=o(d,[["render",i]]);export{p as __pageData,m as default};
